	"function oneShot() {",
	"\tconst argv = apArgv();",
	"\treturn argv[2] === \"run\" || (argv[2] === \"serve\" && argv.indexOf(\"--stdio\") !== -1);",
	"}",
	"",
	"function exitAuthArgs() {",
	"\t// [] : no credential header. null : send nothing. [..] : curl arguments.",
	"\tif (!AP_CONFIG.direct) return [];",
	"\tconst home = homeDir();",
	"\tif (!home) return null;",
	"\tconst file = path.join(home, AP_AGENTPULSE_DIR, AP_AUTH_HEADER_FILE);",
	"\tlet fd;",
	"\ttry {",
	"\t\tfd = fs.openSync(file, fs.constants.O_RDONLY | fs.constants.O_NOFOLLOW);",
	"\t\tconst st = fs.fstatSync(fd);",
	"\t\tif (!st.isFile()) return null;",
	"\t\tif (apPlatform() !== \"win32\") {",
	"\t\t\tconst getuid = apGetuid();",
