	"\t\t\t\t\t\"-o\",",
	"\t\t\t\t\t\"/dev/null\",",
	"\t\t\t\t\t\"-X\",",
	"\t\t\t\t\t\"POST\",",
	"\t\t\t\t\t\"--data-binary\",",
	"\t\t\t\t\t\"@-\",",
	"\t\t\t\t\t\"-H\",",
	"\t\t\t\t\t\"Content-Type: application/json\",",
	"\t\t\t\t\t\"-H\",",
	"\t\t\t\t\t\"X-Agent-Type: opencode\",",
	"\t\t\t\t\t\"-H\",",
