	"\t\trec.gateWaiters.push(resolve);",
	"\t});",
	"}",
	"",
	"function releaseGate(rec) {",
	"\tconst next = rec.gateWaiters.shift();",
	"\tif (next) next();",
	"\telse rec.gateActive -= 1;",
	"}",
	"",
	"async function runGate(rec, home, dir, key) {",
