	"\t\t\t\t\tprocess.kill(-child.pid, \"SIGKILL\");",
	"\t\t\t\t} catch {",
	"\t\t\t\t\ttry {",
	"\t\t\t\t\t\tchild.kill(\"SIGKILL\");",
	"\t\t\t\t\t} catch {",
	"\t\t\t\t\t\t// already gone",
	"\t\t\t\t\t}",
	"\t\t\t\t}",
	"\t\t\t\tfinish({ send: false, cache: false });",
