	"\t} finally {",
	"\t\treleaseGate(rec);",
	"\t}",
	"}",
	"",
	"// ---- helpers shared by both lines ---------------------------------------------",
	"",
	"function envelopeBase(line, version, sid, parent, cwd) {",
