	"\t\t// With several instances in one process, a session of unknown directory has no safe owner: judged as unknown, it is dropped when rules exist.",
	"\t\tconst own = info.dir || (rec.instances <= 1 ? ctxDir : undefined);",
	"\t\tconst env = envelopeBase(",
	"\t\t\t1,",
	"\t\t\tinfo.version || lastVersion,",
	"\t\t\tsid,",
	"\t\t\troot !== sid ? root : undefined,",
	"\t\t\town,",
	"\t\t);",
	"\t\tenv.hook_event_name = name;",
	"\t\tenv.data = data;",
