	"\t\t\tevt: opts && opts.evt,",
	"\t\t\tkey: opts && opts.key,",
	"\t\t});",
	"\t}",
	"",
	"\tfunction isChild(sid) {",
	"\t\tconst info = sessionInfo(rec, sid);",
	"\t\treturn !!(info && info.parent);",
	"\t}",
	"",
	"\tfunction finishCall(sid, callID, entry, status) {",
